const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const root=path.join(__dirname,'..'),css=fs.readFileSync(path.join(root,'experience/light-mode.css'),'utf8'),html=fs.readFileSync(path.join(root,'index.html'),'utf8');
test('Dynamic lesson labels receive the existing accessibility enhancement on every lens switch',()=>{const show=html.slice(html.indexOf('function show(host,panel,t,k,init)'),html.indexOf('function mount(host,t)',html.indexOf('function show(host,panel,t,k,init)')));assert.match(show,/AppDesign\.enhance\(panel\)/);});
test('Light readouts, inline captions and relationship labels have scoped colour repairs',()=>{for(const selector of ['.lx-step>span:first-child','.lx-card .k2','.lx-slider>b','.lx-stat .v3>span','.lx-apps>span:first-child','.lw-n','.kg-row .ty'])assert.ok(css.includes('html.pe-refined[data-theme=light] '+selector),selector);assert.doesNotMatch(css,/filter:|opacity:|canvas\{/);});
test('Scientific stages keep dark backgrounds together with light labels, without filtering traces',()=>{for(const selector of ['.lf-shell','.l-sim','.lx-stage','.cmp-cell','.rs-app','.eqviz .ev-graph'])assert.ok(css.includes(selector));for(const token of ['--bg:var(--obs-night)','--ink:var(--obs-ink)','--ink-faint:var(--obs-dim)','color-scheme:dark'])assert.ok(css.includes(token));});
